from __future__ import annotations

from fastapi import APIRouter
from fastapi.responses import HTMLResponse


def capability_console_router(runtime):
    router = APIRouter(prefix='/capabilities', tags=['capability-console'])

    @router.get('/api/status')
    def status():
        future = runtime.get('future_intelligence')
        phases = future.status() if future is not None else {}
        return {
            'product': 'Vishnu',
            'surface': 'P4-P10 Capability Console',
            'runtime_ready': future is not None,
            'p3_qualification_present': runtime.get('p3_qualification') is not None,
            'voice_qualification_present': runtime.get('voice_qualification') is not None,
            'second_brain_present': runtime.get('second_brain') is not None,
            'continuity_present': runtime.get('continuity') is not None,
            'automation_present': runtime.get('automations') is not None,
            'proactive_present': runtime.get('proactive') is not None,
            'phases': phases,
            'qualification_notice': 'Implementation status is not real-device or production qualification evidence.',
        }

    @router.get('', response_class=HTMLResponse, include_in_schema=False)
    @router.get('/', response_class=HTMLResponse, include_in_schema=False)
    def page():
        return HTMLResponse(_PAGE, headers={'Cache-Control': 'no-store'})

    return router


_PAGE = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#07090d"><title>Vishnu · Capability Console</title>
<style>
:root{color-scheme:dark;font-family:-apple-system,BlinkMacSystemFont,"SF Pro Display",Inter,sans-serif;background:#07090d;color:#f5f7fb}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% 15%,#172033 0,#090c12 38%,#050609 100%);min-height:100dvh}
main{max-width:900px;margin:auto;padding:max(22px,env(safe-area-inset-top)) 18px max(30px,env(safe-area-inset-bottom))}
header{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:28px}.brand{font-weight:750}.pill{border:1px solid #303849;border-radius:999px;padding:7px 10px;font-size:12px;color:#bec8da}
h1{font-size:32px;line-height:1.05;margin:12px 0 8px}.sub{color:#9ba6b8;line-height:1.45;margin:0 0 24px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}.card{background:rgba(16,21,31,.78);border:1px solid #252d3b;border-radius:20px;padding:18px;min-height:160px;backdrop-filter:blur(18px)}
.top{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.phase{font-weight:750;font-size:18px}.state{font-size:11px;border-radius:999px;padding:5px 8px;border:1px solid #35415a;color:#ccd5e4;max-width:120px;text-align:right}.ok{border-color:#285d47;color:#aee6c8}.locked{border-color:#64464f;color:#edbdc7}.desc{color:#9ca8bb;font-size:13px;line-height:1.45;margin-top:14px}.foundation{display:flex;flex-wrap:wrap;gap:7px;margin-top:14px}.chip{font-size:11px;padding:5px 7px;border-radius:999px;background:#101724;border:1px solid #263248;color:#aebbd0}.footer{margin-top:20px;padding:16px;border:1px solid #252d3b;border-radius:18px;color:#8f9bad;font-size:12px;line-height:1.5}.dot{width:8px;height:8px;border-radius:50%;display:inline-block;background:#73d7a5;box-shadow:0 0 12px #73d7a5;margin-right:7px}
section.manager{margin-top:24px;padding:18px;border:1px solid #252d3b;border-radius:20px;background:rgba(16,21,31,.78)}.manager h2{font-size:21px;margin:0 0 8px}.manager p{color:#9ca8bb;font-size:13px;line-height:1.45}.forms{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px}.form{padding:14px;border:1px solid #303849;border-radius:16px}.form label{display:block;font-size:12px;color:#aebbd0;margin:10px 0 5px}.form input,.form textarea,.cap textarea{width:100%;background:#080b11;color:#f5f7fb;border:1px solid #303849;border-radius:10px;padding:10px;font:inherit;font-size:13px}.form textarea,.cap textarea{min-height:110px;resize:vertical}.button{background:#dce8ff;color:#101725;border:0;border-radius:10px;padding:9px 12px;font-weight:700;margin:8px 6px 2px 0;cursor:pointer}.button.secondary{background:#1b2535;color:#dce8ff;border:1px solid #35415a}.cap-list{display:grid;gap:10px;margin-top:14px}.cap{padding:14px;border:1px solid #303849;border-radius:14px;background:#0a0e16}.cap h3{font-size:15px;margin:0 0 6px;overflow-wrap:anywhere}.cap small,.cap .meta{display:block;color:#99a6ba;font-size:12px;line-height:1.5;overflow-wrap:anywhere}.cap .tools{margin:10px 0 0 12px;padding-left:12px;border-left:1px solid #35415a}.cap .attest{display:flex;gap:8px;align-items:flex-start;color:#d1d9e7;font-size:12px;margin-top:10px}.cap .attest input{margin-top:2px}.notice{color:#9ba6b8;font-size:12px;margin-top:10px;min-height:18px}
</style></head><body><main>
<header><div class="brand">Vishnu</div><div class="pill"><span class="dot"></span><span id="runtime">Checking runtime</span></div></header>
<h1>Capability Console</h1><p class="sub">Live read-only view of the P4–P10 software foundations and their qualification locks. This console never grants authority or marks a phase qualified.</p>
<div id="grid" class="grid"></div>
<section class="manager" aria-labelledby="manager-title"><h2 id="manager-title">API and MCP management</h2><p>Import OpenAPI documents or register an MCP server, inspect discovered tools, and approve read-only operations. Owner approval requires an active session with recent reauthentication. Credentials are sent directly to Vishnu and are not shown again.</p>
<div class="forms"><div class="form"><strong>Discover OpenAPI operations</strong><label for="openapi-json">OpenAPI 3 document (JSON)</label><textarea id="openapi-json" placeholder='{"openapi":"3.1.0","servers":[{"url":"https://api.example.com"}],"paths":{}}'></textarea><button class="button" id="import-openapi">Import document</button></div>
<div class="form"><strong>Connect an MCP server</strong><label for="mcp-name">Server name</label><input id="mcp-name" maxlength="120" autocomplete="off"><label for="mcp-url">Streamable HTTP endpoint (HTTPS)</label><input id="mcp-url" type="url" maxlength="2048" placeholder="https://server.example/mcp" autocomplete="url"><button class="button" id="add-mcp">Add server</button></div></div>
<div class="notice" id="manager-notice" role="status"></div><h2>Discovered capabilities</h2><div id="manager-list" class="cap-list"></div></section>
<div class="footer" id="footer">Loading implementation status…</div>
<script>
const descriptions={p4:'Everyday Personal Intelligence · briefing, goals, reminders, follow-ups, attention and context.',p5:'Deep Second Brain · Life Graph, timeline, causal relationships and evidence-backed decision context.',p6:'Autonomous Personal Operations · long-horizon plans with governed approval boundaries.',p7:'Multimodal World Understanding · screen, camera, image, document, audio, location, sensors and wearables.',p8:'Vishnu Everywhere · unified identity and continuity across device surfaces.',p9:'Sovereign / Hybrid Intelligence · privacy-aware local, private and cloud model routing.',p10:'Advanced Autonomous Intelligence · agents, long-horizon planning, evaluation, learning and strategy.'};
const names={p4:'P4 · Everyday Intelligence',p5:'P5 · Deep Second Brain',p6:'P6 · Personal Operations',p7:'P7 · World Understanding',p8:'P8 · Everywhere',p9:'P9 · Hybrid Intelligence',p10:'P10 · Advanced Intelligence'};
const notice=document.getElementById('manager-notice');
async function api(path,method='GET',body){const response=await fetch(path,{method,credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.detail?.message||data.detail||`Request failed (${response.status})`);return data}
function button(text,handler,secondary=false){const b=document.createElement('button');b.className='button'+(secondary?' secondary':'');b.textContent=text;b.onclick=handler;return b}
function field(label,value='{}'){const box=document.createElement('div');const l=document.createElement('label');l.textContent=label;const area=document.createElement('textarea');area.value=value;box.append(l,area);return {box,area}}
function capCard(item){const el=document.createElement('article');el.className='cap';const title=document.createElement('h3');title.textContent=item.name||item.id;const meta=document.createElement('span');meta.className='meta';meta.textContent=[item.type==='mcp_tool'?'MCP tool':item.method||'OpenAPI',item.path||item.server_url||'',item.connection?.status||'discovered'].filter(Boolean).join(' · ');el.append(title,meta);
if(item.type==='mcp_server'){const token=document.createElement('input');token.type='password';token.autocomplete='new-password';token.placeholder='Optional bearer token';token.setAttribute('aria-label','Optional MCP bearer token');el.append(token,button('Connect and discover tools',async()=>{try{notice.textContent='Connecting…';await api(`/iphone/api/apps-tools/mcp/servers/${encodeURIComponent(item.id)}/discover`,'POST',token.value?{auth_type:'bearer_token',api_key:token.value}:{auth_type:'none'});token.value='';notice.textContent='MCP tools discovered.';await loadManager()}catch(e){notice.textContent=e.message}}));if(item.connection?.status==='connected')el.append(button('Disconnect MCP server',async()=>{try{await api(`/iphone/api/apps-tools/mcp/servers/${encodeURIComponent(item.id)}/disconnect`,'POST',{});notice.textContent='MCP server disconnected.';await loadManager()}catch(e){notice.textContent=e.message}},true));for(const tool of item.tools||[]){const child=capCard(tool);child.classList.add('tools');el.append(child)}return el}
if(item.type==='mcp_tool'){if(item.connection?.status==='connected'){const args=field('Arguments (JSON)');el.append(args.box,button('Execute approved MCP tool',async()=>{try{notice.textContent='Executing…';const result=await api(`/iphone/api/apps-tools/capabilities/${encodeURIComponent(item.id)}/execute`,'POST',{parameters:JSON.parse(args.area.value||'{}')});notice.textContent='MCP response verified: '+JSON.stringify(result.result).slice(0,1200)}catch(e){notice.textContent=e.message}}))}else{const attest=document.createElement('label');attest.className='attest';const check=document.createElement('input');check.type='checkbox';const text=document.createElement('span');text.textContent='I reviewed this tool and attest that it only reads data.';attest.append(check,text);el.append(attest,button('Approve read-only tool',async()=>{if(!check.checked){notice.textContent='Review and attest before approving.';return}try{await api(`/iphone/api/apps-tools/mcp/capabilities/${encodeURIComponent(item.id)}/approve`,'POST',{read_only_attested:true});notice.textContent='MCP read-only tool approved.';await loadManager()}catch(e){notice.textContent=e.message}}))}return el}
const auth=document.createElement('input');auth.type='password';auth.autocomplete='new-password';auth.placeholder='Optional bearer token';auth.setAttribute('aria-label','Optional API bearer token');el.append(auth);if(item.connection?.status==='connected'){const args=field('Declared operation parameters (JSON)');el.append(args.box,button('Execute read-only GET',async()=>{try{const result=await api(`/iphone/api/apps-tools/capabilities/${encodeURIComponent(item.id)}/execute`,'POST',{parameters:JSON.parse(args.area.value||'{}')});notice.textContent='API response verified: '+JSON.stringify(result.result).slice(0,1200)}catch(e){notice.textContent=e.message}}),button('Disconnect',async()=>{try{await api(`/iphone/api/apps-tools/capabilities/${encodeURIComponent(item.id)}/disconnect`,'POST',{});notice.textContent='Capability disconnected.';await loadManager()}catch(e){notice.textContent=e.message}},true))}else{el.append(button('Approve and connect',async()=>{try{await api(`/iphone/api/apps-tools/capabilities/${encodeURIComponent(item.id)}/connect`,'POST',auth.value?{auth_type:'bearer_token',api_key:auth.value}:{auth_type:'none'});auth.value='';notice.textContent='OpenAPI capability approved and connected.';await loadManager()}catch(e){notice.textContent=e.message}}))}return el}
async function loadManager(){const root=document.getElementById('manager-list');try{const [caps,servers]=await Promise.all([api('/iphone/api/apps-tools/capabilities?limit=100'),api('/iphone/api/apps-tools/mcp/servers')]);root.replaceChildren();for(const item of caps.capabilities||[]){if(item.type==='mcp_server'||item.type==='mcp_tool')continue;root.append(capCard(item))}for(const server of servers.servers||[])root.append(capCard(server));if(!root.children.length)root.textContent='No discovered capabilities yet.'}catch(e){root.textContent=e.message}}
document.getElementById('import-openapi').onclick=async()=>{try{const documentValue=JSON.parse(document.getElementById('openapi-json').value);const result=await api('/iphone/api/apps-tools/capabilities/openapi','POST',{document:documentValue});notice.textContent=`Imported ${result.discovered} inert operations.`;await loadManager()}catch(e){notice.textContent=e.message}};
document.getElementById('add-mcp').onclick=async()=>{try{await api('/iphone/api/apps-tools/mcp/servers','POST',{name:document.getElementById('mcp-name').value,url:document.getElementById('mcp-url').value});notice.textContent='MCP server saved. Connect to discover tools.';await loadManager()}catch(e){notice.textContent=e.message}};
async function load(){try{const r=await fetch('/capabilities/api/status',{cache:'no-store'});const d=await r.json();document.getElementById('runtime').textContent=d.runtime_ready?'Runtime online':'Runtime unavailable';const g=document.getElementById('grid');g.replaceChildren();for(const key of ['p4','p5','p6','p7','p8','p9','p10']){const p=d.phases[key]||{};const active=String(p.activation||'').toLowerCase()==='safe-now';const el=document.createElement('article');el.className='card';const top=document.createElement('div');top.className='top';const phase=document.createElement('div');phase.className='phase';phase.textContent=names[key];const state=document.createElement('div');state.className='state '+(active?'ok':'locked');state.textContent=active?'SAFE NOW':'GATED';top.append(phase,state);const desc=document.createElement('div');desc.className='desc';desc.textContent=descriptions[key];const foundation=document.createElement('div');foundation.className='foundation';const implemented=document.createElement('span');implemented.className='chip';implemented.textContent='Implemented: '+(p.implemented===true?'yes':'no');const activation=document.createElement('span');activation.className='chip';activation.textContent=p.activation||'status unavailable';foundation.append(implemented,activation);el.append(top,desc,foundation);g.append(el)}document.getElementById('footer').textContent=d.qualification_notice+' · P3 recorder: '+(d.p3_qualification_present?'present':'missing')+' · Second Brain: '+(d.second_brain_present?'present':'missing')+' · Continuity: '+(d.continuity_present?'present':'missing')+' · Automation: '+(d.automation_present?'present':'missing');}catch(e){document.getElementById('runtime').textContent='Unavailable';document.getElementById('footer').textContent='Could not read runtime status: '+e.message}}
load();loadManager();setInterval(load,15000);
</script></main></body></html>'''
